#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Qaiyo Admin Booster — i18n build script.

The PHP source language is English (Qaiyo i18n standard). This script generates
the .pot template plus hu_HU / de_DE / fr_FR / es_ES .po and .mo files.

Run from anywhere:  python3 languages/build-translations.py
"""

import os
import sys
import struct

DOMAIN = "qaiyo-admin-booster"
LANG_DIR = os.path.dirname(os.path.abspath(__file__))

sys.path.insert(0, LANG_DIR)
from extra_translations import EXTRA  # noqa: E402  (en -> (ja, pt_PT, it_IT, ru_RU, tr_TR, pl_PL))

# Qaiyo i18n szabvány: EN + 10 fordítás.
# code -> ("T", col) a meglévő 5-oszlopos T listából, vagy ("X", idx) az EXTRA-ból.
LANGS = {
    "hu_HU": ("T", 1),
    "de_DE": ("T", 2),
    "fr_FR": ("T", 3),
    "es_ES": ("T", 4),
    "ja":    ("X", 0),
    "pt_PT": ("X", 1),
    "it_IT": ("X", 2),
    "ru_RU": ("X", 3),
    "tr_TR": ("X", 4),
    "pl_PL": ("X", 5),
}


def translate(en, source, idx):
    """A fordítás egy adott nyelvre: T-oszlop vagy EXTRA-pozíció, angol fallbackkal."""
    if source == "T":
        for row in T:
            if row[0] == en:
                return row[idx]
        return en
    vals = EXTRA.get(en)
    if vals and idx < len(vals) and vals[idx]:
        return vals[idx]
    return en

