# --- Duplikalt msgid-k osszevonasa -----------------------------------------
# Ugyanaz az angol szoveg tobb helyen is szerepelhet a forrasban (pl. a Modulok
# racs Pro-cimei megegyeznek a Pro-katalogus cimeivel). A .po/.mo formatumban
# viszont egy msgid csak EGYSZER allhat: a msgfmt fatalis hibaval elszall a
# duplikatumon. Az elso elofordulast tartjuk meg.
_seen = set()
_unique = []
_dupes = []
for _row in T:
    if _row[0] in _seen:
        _dupes.append(_row[0])
        continue
    _seen.add(_row[0])
    _unique.append(_row)
if _dupes:
    print("Note: %d duplicate msgid(s) collapsed: %s"
          % (len(_dupes), ", ".join(sorted(set(_dupes)))))
T = _unique


def po_escape(s):
    return s.replace("\\", "\\\\").replace('"', '\\"')


def write_po(path, source, idx, lang_code):
    lines = [
        'msgid ""',
        'msgstr ""',
        '"Project-Id-Version: Qaiyo Admin Booster\\n"',
        '"Language: %s\\n"' % lang_code,
        '"MIME-Version: 1.0\\n"',
        '"Content-Type: text/plain; charset=UTF-8\\n"',
        '"Content-Transfer-Encoding: 8bit\\n"',
        "",
    ]
    for row in T:
        lines.append('msgid "%s"' % po_escape(row[0]))
        lines.append('msgstr "%s"' % po_escape(translate(row[0], source, idx)))
        lines.append("")
    open(path, "w", encoding="utf-8").write("\n".join(lines))


def write_pot(path):
    lines = [
        'msgid ""',
        'msgstr ""',
        '"Project-Id-Version: Qaiyo Admin Booster\\n"',
        '"MIME-Version: 1.0\\n"',
        '"Content-Type: text/plain; charset=UTF-8\\n"',
        '"Content-Transfer-Encoding: 8bit\\n"',
        "",
    ]
    for row in T:
        lines.append('msgid "%s"' % po_escape(row[0]))
        lines.append('msgstr ""')
        lines.append("")
    open(path, "w", encoding="utf-8").write("\n".join(lines))


def write_mo(path, source, idx):
    entries = []
    for row in T:
        entries.append((row[0].encode("utf-8"), translate(row[0], source, idx).encode("utf-8")))
    header = ("Project-Id-Version: Qaiyo Admin Booster\n"
              "MIME-Version: 1.0\n"
              "Content-Type: text/plain; charset=UTF-8\n"
              "Content-Transfer-Encoding: 8bit\n")
    entries.insert(0, (b"", header.encode("utf-8")))
    entries.sort(key=lambda e: e[0])
    n = len(entries)
    ktab, vtab = [], []
    k_off = 7 * 4 + 16 * n
    for k, _ in entries:
        ktab.append((len(k), k_off))
        k_off += len(k) + 1
    v_off = k_off
    for _, v in entries:
        vtab.append((len(v), v_off))
        v_off += len(v) + 1
    out = b""
    out += struct.pack("I", 0x950412de)
    out += struct.pack("i", 0)
    out += struct.pack("i", n)
    out += struct.pack("i", 7 * 4)
    out += struct.pack("i", 7 * 4 + 8 * n)
    out += struct.pack("i", 0)
    out += struct.pack("i", 7 * 4 + 16 * n)
    for length, off in ktab:
        out += struct.pack("ii", length, off)
    for length, off in vtab:
        out += struct.pack("ii", length, off)
    for k, _ in entries:
        out += k + b"\x00"
    for _, v in entries:
        out += v + b"\x00"
    open(path, "wb").write(out)


def check_extra_coverage():
    """Minden T-beli angol stringnek legyen EXTRA fordítása (különben angol fallback)."""
    missing = [row[0] for row in T if row[0] not in EXTRA]
    if missing:
        print("WARNING: %d string(s) missing from EXTRA (English fallback used):" % len(missing))
        for m in missing:
            print("  - %s" % m)
    return not missing


if __name__ == "__main__":
    ok = check_extra_coverage()
    write_pot(os.path.join(LANG_DIR, "%s.pot" % DOMAIN))
    for code, (source, idx) in LANGS.items():
        write_po(os.path.join(LANG_DIR, "%s-%s.po" % (DOMAIN, code)), source, idx, code)
        write_mo(os.path.join(LANG_DIR, "%s-%s.mo" % (DOMAIN, code)), source, idx)
    print("Generated .pot + %d languages (po + mo).%s" % (len(LANGS), "" if ok else " [with English fallbacks]"))
